import re

def parse_duration(text):
    if not text:
        return None

    # Case 1: Simple string of digits represents seconds
    if text.isdigit():
        return int(text)

    # Case 2: Unit strings (hours, minutes, seconds) in strict order
    # Regex ensures that only h, m, and s appear in that order, each preceded by digits
    match = re.fullmatch(r'(\d+h)?(\d+m)?(\d+s)?', text)
    if not match:
        return None

    h_str, m_str, s_str = match.groups()

    # If the regex matched but no units were actually found (e.g. an empty match), return None
    if h_str is None and m_str is None and s_str is None:
        return None

    total_seconds = 0
    if h_str:
        total_seconds += int(h_str[:-1]) * 3600
    if m_str:
        total_seconds += int(m_str[:-1]) * 60
    if s_str:
        total_seconds += int(s_str[:-1])

    return total_seconds
